import{_ as t,H as p,f as a,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"精装版译者序向着未来而生","description":"","frontmatter":{},"headers":[],"relativePath":"黑客与画家/精装版译者序向着未来而生.md","filePath":"黑客与画家/精装版译者序向着未来而生.md","lastUpdated":1795561874000}'),_={name:"黑客与画家/精装版译者序向着未来而生.md"};function r(l,e,n,o,s,d){return p(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="精装版译者序向着未来而生" tabindex="-1">精装版译者序向着未来而生 <a class="header-anchor" href="#精装版译者序向着未来而生" aria-label="Permalink to &quot;精装版译者序向着未来而生&quot;">​</a></h1><p>不久前，收到朱巍编辑的来信。她说《黑客与画家》即将出版精装本，希望我作为译者，能写一些感言。</p><p>我这才惊觉，距离我动手翻译，已经过去了三年。真是时光催人老，三年前我坐在同一张书桌前，使用同一个键盘，一字一字地输入译文，宛如发生在昨日。</p><p>回想起来，那时心里没有把握，不知道中文版会不会被中国读者接受。IT 图书的生命周期很短，三四年前的出版物往往已经过时，而《黑客与画家》的英文版出版于 2004 年，其中不少文章写于 2001 年。现在推出中文版会不会太迟了？</p><p>事实证明，我的担心是多余的。中文版上市后，引起了巨大的反响，在国内 IT 业界受到广泛的肯定，很多程序员和项目经理读后表示深受启发，很多计算机系的老师将此书列为学生的推荐读物。我也收到了许多读者来信，摘录几封：</p><ul><li>“……我这两天一直在看，有醍醐灌顶的感觉。”“……我觉得自己看得好还不过瘾，又向学校图书馆荐购了。”“……我们团队人手一本《黑客与画家》，并且至今共赠送了近百本给我们的用户。”</li></ul><p>我一方面很高兴，另一方面也很赞叹保罗·格雷厄姆。他是怎么做到让一本技术书吸引十年后的读者的呢？</p><p>后来，我总结出两个原因。第一，他写的不是技术，而是技术背后的思想。就像数学一样，正确的思想是不会过时的。第二，他的着眼点是长远的未来。文章内容主要不是分析现状，更不是总结过去，而是展望未来，以未来指导现在。举例来说，第 11 章“一百年后的编程语言”就是研究一百年后人们会怎么编程，从而推导出我们现在应该如何编程。除了他以外，我没见过其他人有这种视角。另一个证据是，格雷厄姆最大的成就就是建立创业孵化器 YCombinator。这说明他对未来有精准的眼光，只有知道未来会怎样，才能选出最值得投资的创业公司。</p><p>正是因为这两个原因，《黑客与画家》完全没有过时。十年后的读者，一方面被已经实现的预言震撼（比如，格雷厄姆在 2001 年说，如果苹果公司将 iPod 升级成能上网的手机，就能战胜微软公司），另一方面又被那些还没实现的预言说动（比如，Lisp 语言将成为主流），从而思考自己的选择。这是此书成功的最主要原因，也就是说，它能帮你看清道路。</p><p>德国哲学家马丁·海德格尔（Martin Heidegger）说过一句著名的话：人应该“向死而生”（Being-toward-death）。意思是人面对死亡，才会停止那些无谓琐碎的关注和困扰，体会到什么是重要的事情，从而达到真正的存在。借用这种说法，我觉得格雷厄姆的哲学是“向着未来而生”（Being-toward-future）。也就是说，我们的目光应该盯着未来的世界，以此决定人生应该怎么走。</p><p>说到未来的世界，我想起 2012 年年底，美国国家情报委员会发表了提交给总统的报告《全球趋势 2030》，其中一个主要结论是：</p><ul><li>“……到了 2030 年，没有一个国家——无论是美国、中国或任何其他大国——将成为超级霸权。相反，权力在国家之间变得分散，而且会从国家手中向非正式的网络以及个人扩散，产生深刻的影响。……个人和小团体的力量将进一步被增强，更易获得各种调用资源的能力，在解决全球性挑战方面可能更有力。”</li></ul><p>如果这种预测是正确的，就意味着未来 20 年里，政府的力量将缩小，个人和小团体将崛起，成为推动社会前进的主要力量。在这个过程中，互联网和计算机必然将扮演重要角色，因为正是它们使个体的影响力实现了指数式提升。</p><p>对于网络创业者来说，这是最好的时代。只要把握大趋势，技术就会把个人送到难以想象的高度。</p><p>未来就在眼前，伸手可及。《黑客与画家》就是这次旅程的指南，为你指出通往那扇门的方向。正如格雷厄姆所说，你要做的就是“活在未来，然后造出现在还没有的部分”（Live in thefuture, then build what&#39;s missing）。</p><ul><li><p>阮一峰</p></li><li><p>2013 年 03 月 29 日</p></li></ul>',16)])])}const f=t(_,[["render",r]]);export{c as __pageData,f as default};
